mapper.select:
select order_item.ORDER_ITEM_ID, order_item.PROJECT_ID, order_item.SOU_ITEM_ID, order_item.ORDER_ID, order_item.order_round, order_item.ORDER_STATUS, order_item.VENDOR_ID, order_item.LAST_UPDATE_DATE, vendor.VENDOR_CODE, vendor.VENDOR_NAME, order_item.MONTHLY_PRODUCTION, order_item.ORDER_NOTAX_PRICE, order_item.ORDER_TAX_PRICE, project.ORDER_END_TIME, item.ITEM_DESC, item.AFFILIATED_UNIT, item.METERING_UNIT, vendor.VENDOR_NAME from scc_sou_order_item order_item left join scc_sou_item item on order_item.SOU_ITEM_ID = item.SOU_ITEM_ID left join scc_sou_vendor vendor on vendor.VENDOR_ID = order_item.VENDOR_ID and vendor.PROJECT_ID = #{projectId} left join scc_sou_project project on project.PROJECT_ID = order_item.PROJECT_ID where order_item.ORDER_STATUS = 'SUBMISSION' and order_item.PROJECT_ID =#{projectId}
and order_item.ITEM_CODE like concat('%', concat(#{itemCode}, '%'))
and order_item.ITEM_DESC like concat('%', concat(#{itemDesc}, '%'))
and item.ORG_OU_CODE = #{orgOuCode}
and item.ORG_OU_NAME like concat('%', concat(#{orgOuName}, '%'))
and item.ORG_INV_CODE = #{orgInvCode}
and item.ORG_INV_NAME like concat('%', concat(#{orgInvName}, '%'))
and item.ITEM_GROUP like concat('%', concat(#{itemGroup}, '%'))
and order_item.VENDOR_ID = #{vendorId}
and vendor.VENDOR_NAME like concat('%', concat(#{vendorName}, '%'))
and order_item.WIN_STATUS = #{winStatus}
and order_item.SELECT_STATUS = #{selectStatus}
and order_item.ROUND = #{round}
and order_item.RANKING = #{ranking}
and order_item.ORDER_STATUS = 'SUBMISSION'
and order_item.ROUND != project.CURRENT_ROUND
AND project.ORDER_END_TIME >= #{quoteTimeFrom}
AND project.ORDER_END_TIME <= #{quoteTimeTo}
AND order_item.ORDER_TAX_PRICE >= #{quoteFrom}
AND order_item.ORDER_TAX_PRICE <= #{quoteTo}

select order_item.order_result_id, order_item.PROJECT_ID, order_item.SOU_ITEM_ID, order_item.ORDER_ID, order_item.PERIOD_VENDOR_ID, order_item.THIRD_VENDOR_ID, order_item.SECOND_VENDOR_ID, order_item.MAX_VENDOR_ID, order_item.AFFILIATED_UNIT, order_item.MONTHLY_PRODUCTION, order_item.MAX_PRICE, order_item.SECOND_PRICE, order_item.THIRD_PRICE, order_item.PERIOD_PRICE, order_item.MONTH_TOTAL_AMOUNT, order_item.MAX_VENDOR_NAME, order_item.SECOND_VENDOR_NAME, order_item.THIRD_VENDOR_NAME, order_item.PERIOD_VENDOR_NAME, order_item.win_status, order_item.select_status, order_item.ORDER_REMARK, order_item.SELECT_REMARK, order_item.WIN_NOTICE_REMARK, order_item.RESULT_STATUS, order_item.WIN_NOTICE_STATUS, order_item.ITEM_DESC, order_item.ORDER_ROUND, order_item.WIN_VENDOR_ID, order_item.WIN_VENDOR_NAME, order_item.WIN_VENDOR_PRICE, order_item.DIFFERENCE_RATE from scc_sou_order_result order_item where order_item.PROJECT_ID =#{projectId} and order_item.select_status ='WIN'
and order_item.ITEM_CODE like concat('%', concat(#{itemCode}, '%'))
and order_item.ITEM_DESC like concat('%', concat(#{itemDesc}, '%'))
and order_item.VENDOR_ID = #{vendorId}
and order_item.WIN_STATUS = #{winStatus}
and order_item.SELECT_STATUS = #{selectStatus}
and order_item.ROUND = #{round}
and order_item.RANKING = #{ranking}
and order_item.ORDER_STATUS = 'SUBMISSION'
and order_item.ROUND != project.CURRENT_ROUND
AND order_item.ORDER_TAX_PRICE >= #{quoteFrom}
AND order_item.ORDER_TAX_PRICE <= #{quoteTo}

select
order_item.ORDER_ITEM_ID,               
order_item.PROJECT_ID,                  
order_item.SOU_ITEM_ID,                 
order_item.ORDER_ID,                    
order_item.order_round,                       
order_item.ORDER_STATUS,                
order_item.VENDOR_ID,                   
order_item.ORDER_NOTAX_PRICE,           
order_item.ORDER_TAX_PRICE,              
project.ORDER_END_TIME,              
item.ITEM_DESC,              
item.AFFILIATED_UNIT,              
vendor.VENDOR_NAME              
from scc_sou_order_item_his order_item
left join scc_sou_item item on order_item.SOU_ITEM_ID = item.SOU_ITEM_ID
left join scc_sou_vendor vendor  on order_item.PROJECT_ID = vendor.PROJECT_ID  AND  order_item.vendor_id = vendor.vendor_id
left join scc_sou_project project on order_item.PROJECT_ID = project.PROJECT_ID
where
 order_item.ORDER_STATUS = 'SUBMISSION'
and order_item.PROJECT_ID =#{projectId}

    and order_item.ITEM_CODE like concat('%', concat(#{itemCode}, '%'))


    and order_item.ITEM_DESC like concat('%', concat(#{itemDesc}, '%'))


    and item.ORG_OU_CODE = #{orgOuCode}


    and item.ORG_OU_NAME like concat('%', concat(#{orgOuName}, '%'))


    and item.ORG_INV_CODE = #{orgInvCode}


    and item.ORG_INV_NAME like concat('%', concat(#{orgInvName}, '%'))


    and item.ITEM_GROUP like concat('%', concat(#{itemGroup}, '%'))


    and order_item.VENDOR_ID = #{vendorId}


    and vendor.VENDOR_NAME like concat('%', concat(#{vendorName}, '%'))


    and order_item.WIN_STATUS = #{winStatus}


    and order_item.SELECT_STATUS = #{selectStatus}


    and order_item.ROUND = #{round}


    and order_item.RANKING = #{ranking}


    and order_item.ORDER_STATUS = 'SUBMISSION'


    and order_item.ROUND != project.CURRENT_ROUND


    AND project.ORDER_END_TIME >= #{quoteTimeFrom}


    AND project.ORDER_END_TIME <= #{quoteTimeTo}


    AND order_item.ORDER_TAX_PRICE >= #{quoteFrom}


    AND order_item.ORDER_TAX_PRICE <= #{quoteTo}


    AND order_item.AFFILIATED_UNIT <= #{affiliatedUnit}
